from collections import deque


def min_knight_moves(x, y):
    x, y = abs(x), abs(y)
    moves = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]
    queue = deque([(0, 0, 0)])
    visited = {(0, 0)}
    limit = max(x, y) + 2

    while queue:
        cx, cy, dist = queue.popleft()
        if (cx, cy) == (x, y):
            return dist
        for dx, dy in moves:
            nx, ny = cx + dx, cy + dy
            if -2 <= nx <= limit and -2 <= ny <= limit and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

